    }

    @Test
    fun `читает записи со сжатием`() {
        val file = zipOf(deflatedEntry("p/001.png", page(7, 200_000)))
        file.channel().use { channel ->
            openZip(channel, file.length()).use { zip ->
                val entry = zip.find("p/001.png")
                assertNotNull(entry, "запись в подпапке не нашлась")
                assertTrue(page(7, 200_000).contentEquals(zip.read(entry!!)), "распакованная страница не совпала")
            }
        }
    }

    @Test
    fun `страницы идут в естественном порядке`() {
        val names = listOf("10.jpg", "2.jpg", "1.jpg", "20.jpg", "003.jpg")
        val file = zipOf(*names.map { zipEntry(it, page(1, 16)) }.toTypedArray())
        file.channel().use { channel ->
            openZip(channel, file.length()).use { zip ->
                assertEquals(
                    listOf("1.jpg", "003.jpg", "2.jpg", "10.jpg", "20.jpg"),
                    zip.imageEntries(setOf("jpg")).map { it.name },
                )
            }
        }
    }

    @Test
    fun `главы тайтла сортируются как числа`() {
        assertEquals(
            listOf("Том 1", "том 2", "Том 10"),
            listOf("Том 10", "том 2", "Том 1").sortedWith { a, b -> naturalOrder(a, b) },
        )
    }

    @Test
    fun `страница больше прежнего лимита читается`() {
        // 64 МБ на запись были причиной, по которой тяжёлый CBR не открывался.
        val big = page(3, 70 * 1024 * 1024)
        val file = zipOf(deflatedEntry("001.jpg", big))
        file.channel().use { channel ->
            openZip(channel, file.length()).use { zip ->
                val entry = zip.find("001.jpg")
                assertNotNull(entry)
                assertEquals(big.size.toLong(), entry!!.compressedSize, "размер в каталоге разошёлся с ожиданием")
                assertTrue(big.contentEquals(zip.read(entry)), "большая страница прочиталась не целиком")
            }
        }
    }

    @Test
    fun `не zip читается как ошибка`() {
        val file = Files.createTempFile("shell", ".cbr").toFile()
        file.writeBytes(ByteArray(5000) { 7 })
        assertThrows(IOException::class.java) {
            file.channel().use { channel -> openZip(channel, file.length()).use { it.entries() } }
        }
    }

    private fun page(seed: Int, size: Int): ByteArray = ByteArray(size) { (it + seed).toByte() }

    private fun zipEntry(name: String, bytes: ByteArray): Pair<String, ByteArray> = name to bytes

    private fun deflatedEntry(name: String, bytes: ByteArray): Triple<String, ByteArray, Boolean> =
        Triple(name, bytes, true)

    private fun zipOf(vararg stored: Pair<String, ByteArray>): File = zip(false, *stored.map { Triple(it.first, it.second, false) })

    private fun zipOf(vararg deflated: Triple<String, ByteArray, Boolean>): File = zip(true, *deflated)

    private fun zip(deflate: Boolean, vararg files: Triple<String, ByteArray, Boolean>): File {
        val file = Files.createTempFile("shell", ".cbz").toFile()
        ZipOutputStream(file.outputStream().buffered()).use { out ->
            files.forEach { (name, bytes, ownMethod) ->
                out.setMethod(
                    if (deflate || ownMethod) ZipEntry.DEFLATED else ZipEntry.STORED,
                )
                out.putNextEntry(ZipEntry(name))
                out.write(bytes)
                out.closeEntry()
            }
        }
        return file
    }

    private fun File.channel(): FileChannel = RandomAccessFile(this, "r").channel
}

