     /** Страницы только одного тома: для открытия читалки сразу на главу. */
     fun pagesOf(volume: Library.Volume): List<Library.Page> {
         if (volume.isArchive) {
             val path = entries(volume.uri) ?: return emptyList()
             return path.map { entry ->
                 Library.Page.InArchive(name = entry.substringAfterLast('/'), archiveUri = volume.uri, entry = entry)
             }
         }
         return listOf(Library.Page.File(name = volume.name, uri = volume.uri))
     }

     /** Последний собранный тайтл по URI папки — чтобы не собирать дважды. */
     private val titleByUri = object : LinkedHashMap<String, Library.Title>(32, 0.75f, true) {
         override fun removeEldestEntry(eldest: Map.Entry<String, Library.Title>?) = size > 32
     }

     private fun titleOfFolderCached(uri: String): Library.Title =
         titleByUri[uri] ?: title(uri, "").also { titleByUri[uri] = it }

     /** Записи архива, в естественном порядке; null, если не архив. */
     private fun entries(uri: String): List<String>? = runCatching {
         val (channel, size) = library.openChannel(uri) ?: return null
         openZip(channel, size).use { zip ->
             zip.imageEntries(Library.IMAGE_EXTENSIONS).map { it.name }
         }
     }.getOrNull()

     /**
      * Байты страницы. Кэш держит несколько страниц вокруг текущей, поэтому
      * листание вперёд-назад не распаковывает архив заново на каждом шаге.
      */
     fun bytes(page: Library.Page): ByteArray? = when (page) {
         is Library.Page.File -> library.readBytes(page.uri)
         is Library.Page.InArchive -> {
             val key = page.archiveUri + '\u0000' + page.entry
             pageCache[key] ?: runCatching {
                 val (channel, size) = library.openChannel(page.archiveUri) ?: return null
                 openZip(channel, size).use { zip ->
                     val entry = zip.find(page.entry) ?: return null
                     zip.read(entry)
                 }
             }.getOrNull()?.also { pageCache[key] = it }
         }
     }

     /** Сбросить кэш страниц: память освобождается, список не трогаем. */
     fun clearCache() = pageCache.clear()

     private companion object {
         const val CACHE_PAGES = 6
         const val MAX_PAGES = 5_000
         const val MAX_NODES = 50_000
         const val MAX_DEPTH = 8
     }
 }
