new = '''    /**
     * Обложка тайтла: первая страница первых глав.
     *
     * Считается лёгким обходом, а не через [title]: тот раскрывает центральный
     * каталог КАЖДОГО архива в папке, и список из сорока папок двадцать минут
     * рисовал серые квадраты вместо обложек. Здесь открывается ровно один
     * архив — первый, из которого и берётся картинка.
     */
    fun coverOf(uri: String): ByteArray? {
        val children = runCatching { list(uri) }.getOrDefault(emptyList())
        // У документа без детей list() пуст — значит, это файл, а не папка.
        if (children.isEmpty()) return firstPageBytes(uri) ?: library.readBytes(uri)
        val ordered = children.sortedWith { a, b -> naturalOrder(a.name, b.name) }
        // Картинка прямо в папке — самая дешёвая обложка: один seek, без ZIP.
        for (node in ordered) {
            if (!node.isDirectory && node.extension in Library.IMAGE_EXTENSIONS) {
                library.readBytes(node.uri)?.let { return it }
            }
        }
        for (node in ordered) {
            if (!node.isDirectory && node.extension in Library.ARCHIVE_EXTENSIONS) {
                firstPageBytes(node.uri)?.let { return it }
            }
        }
        // Вложенные папки: обложка тайтла ищется в них же, иначе папка
        // «Том 1/» с главами осталась бы серой.
        for (node in ordered) {
            if (node.isDirectory) coverOf(node.uri)?.let { return it }
        }
        return null
    }

    /** Первая картинка архива: раскрываем центральный каталог и читаем запись. */
    private fun firstPageBytes(archiveUri: String): ByteArray? = runCatching {
        val (channel, size) = library.openChannel(archiveUri) ?: return null
        openZip(channel, size).use { zip ->
            val entry = zip.imageEntries(Library.IMAGE_EXTENSIONS).firstOrNull() ?: return null
            zip.read(entry)
        }
    }.getOrNull()

