package app.yomikai.shell.library

/**
 * Файл или папка — ровно то, что отдаёт хранилище.
 *
 * Всё остальное в приложении работает только с этим интерфейсом, а не с SAF.
 * Причина не в красоте: SAF нельзя проверить на JVM, а логика библиотеки —
 * это ровно та часть, где в первый раз всё и сломалось. С подменой источника
 * библиотека проверяется обычными тестами на настоящих файлах.
 */
interface Document {
    val uri: String
    val name: String
    val isDirectory: Boolean
    val size: Long
}

/** Источник документов: SAF на устройстве, папка на диске в тестах. */
interface DocumentSource {
    /** Содержимое каталога. Для файла — пустой список. */
    fun children(uri: String): List<Document>

    /** Файл целиком в память. `null`, если нечитаем или больше лимита. */
    fun readBytes(uri: String, maxBytes: Long = Long.MAX_VALUE): ByteArray?

    /**
     * Канал с возможностью seek — нужен для ZIP: запись читается по смещению
     * из локального заголовка, и без seek архив читался бы целиком на каждую
     * страницу.
     */
    fun openChannel(uri: String): SeekableSource?

    /** Канал с seek и известным размером. */
    interface SeekableSource : java.io.Closeable {
        fun position(offset: Long, length: Int): ByteArray
        val size: Long
    }
}

package app.yomikai.shell.library

import java.nio.channels.FileChannel

/**
 * Файл или папка — ровно то, что отдаёт хранилище.
 *
 * Всё остальное в приложении работает только с этим интерфейсом, а не с SAF.
 * Причина не в красоте: SAF нельзя проверить на JVM, а логика библиотеки —
 * это ровно та часть, где в первый раз всё и сломалось. С подменой источника
 * библиотека проверяется обычными тестами на настоящих файлах.
 */
interface Document {
    val uri: String
    val name: String
    val isDirectory: Boolean
    val size: Long
}

/** Источник документов: SAF на устройстве, папка на диске в тестах. */
interface DocumentSource {
    /** Содержимое каталога. Для файла — пустой список. */
    fun children(uri: String): List<Document>

    /** Файл целиком в память. `null`, если нечитаем или больше лимита. */
    fun readBytes(uri: String, maxBytes: Long = Long.MAX_VALUE): ByteArray?

    /**
     * Канал с seek — нужен для ZIP: запись читается по смещению из локального
     * заголовка, и без seek архив читался бы целиком на каждую страницу.
     *
     * Возвращается вместе с размером: у SAF-документа размера нет в URI,
     * а читателю он нужен, чтобы найти центральный каталог с конца файла.
     */
    fun openChannel(uri: String): Opened?
}

/** Открытый файл: канал и его размер. Закрывает канал [close]. */
class Opened(val channel: FileChannel, val size: Long) : java.io.Closeable {
    override fun close() {
        runCatching { channel.close() }
    }
}

package app.yomikai.shell.library

/**
 * Правила локальной библиотеки — ровно как в основном приложении.
 *
 * Здесь нет Android: только чистые решения по [Document], поэтому каждое из
 * них проверяется обычным тестом. В первый раз эти правила были размазаны по
 * SAF-коду, из-за чего проверить их было нечем, и библиотека работала не так,
 * как задумано.
 *
 * Разметка ровно двухуровневая, как в оригинале:
 *
 * ```
 * корень/                ← корень SAF
 *   Манга/               ← манга: папка ИЛИ одиночный архив
 *     Глава.cbz          ← глава: архив, или папка, где есть хоть одна картинка
 *   Одиночная.cbz        ← манга, у которой глава одна и лежит рядом с собой
 * ```
 *
 * Вглубь не ходим: третий уровень в библиотеке не различают, и рекурсивный
 * разворот папок в первый раз превращал вложенные каталоги в кашу.
 */
object LocalRules {

    /** Форматы архивов, которые читаются. `cbr`/`rar` — это libarchive, его нет. */
    val ARCHIVE_EXTENSIONS = setOf("zip", "cbz")

    /** Epub в первой версии не читается: это отдельный парсер с xml внутри. */
    val EPUB_EXTENSIONS = setOf("epub")

    val IMAGE_EXTENSIONS = setOf("jpg", "jpeg", "png", "webp", "gif", "avif", "jxl", "bmp")

    /**
     * Служебные каталоги внутри корня. В оригинале их список задан константой,
     * и они не должны показываться как манга.
     */
    val RESERVED_DIRECTORIES = setOf(
        "local",
        "downloads",
        "backup",
        "autobackup",
        "automatic_backups",
        "covers",
        ".thumbnails",
    )

    fun extensionOf(name: String): String = name.substringAfterLast('.', "").lowercase()

    fun nameWithoutExtension(name: String): String = name.substringBeforeLast('.')

    /** Манга — папка или одиночный архив; скрытое и служебное отбрасывается. */
    fun isManga(document: Document): Boolean {
        if (document.name.isEmpty() || document.name.startsWith('.')) return false
        if (document.isDirectory) {
            return document.name.lowercase() !in RESERVED_DIRECTORIES
        }
        return extensionOf(document.name) in ARCHIVE_EXTENSIONS
    }

    /**
     * Глава — архив, epub или папка, внутри которой есть хоть одна картинка.
     *
     * Проверка «есть ли картинка» обязательна: в папке манги посторонние
     * каталоги (`.thumbnails`, `extras`, пустые папки) иначе выглядели бы
     * главами, и их нечего было бы открывать.
     */
    fun isChapter(document: Document, children: (String) -> List<Document>): Boolean {
        if (document.name.isEmpty() || document.name.startsWith('.')) return false
        return when {
            document.isDirectory -> children(document.uri).any { isImage(it) }
            extensionOf(document.name) in ARCHIVE_EXTENSIONS -> true
            extensionOf(document.name) in EPUB_EXTENSIONS -> true
            else -> false
        }
    }

    fun isImage(document: Document): Boolean =
        !document.isDirectory && extensionOf(document.name) in IMAGE_EXTENSIONS

    /** Имя главы: у папки — как есть, у файла — без расширения. */
    fun chapterName(document: Document): String = if (document.isDirectory) {
        document.name
    } else {
        nameWithoutExtension(document.name)
    }

    /** Имя манги: у папки — как есть, у архива — без расширения. */
    fun mangaName(document: Document): String = if (document.isDirectory) {
        document.name
    } else {
        nameWithoutExtension(document.name)
    }

    /**
     * Есть ли у манги своя обложка `cover.*`.
     *
     * Как в оригинале: имя без расширения сравнивается с `cover` без учёта
     * регистра, расширение должно быть картинным. Иначе обложка генерируется
     * из первой картинки самой ранней главы.
     */
    fun explicitCover(documents: List<Document>): Document? = documents.firstOrNull { candidate ->
        !candidate.isDirectory &&
            nameWithoutExtension(candidate.name).equals("cover", ignoreCase = true) &&
            isImage(candidate)
    }
}

package app.yomikai.shell.library

import app.yomikai.shell.archive.ZipReader
import app.yomikai.shell.archive.naturalOrder
import app.yomikai.shell.archive.openZip

/** Манга: папка или одиночный архив. Главы лежат внутри (см. [LocalRules]). */
data class Manga(
    val uri: String,
    val name: String,
    val isDirectory: Boolean,
    /** Файлы папки манги: нужны для поиска `cover.*`. */
    val children: List<Document>,
)

/** Глава манги: архив, epub или папка с картинками. */
data class Chapter(
    val uri: String,
    val name: String,
    val isDirectory: Boolean,
    /** Признак, что глава — папка: у неё свой каталог картинок. */
    val isFolder: Boolean,
)

/** Страница главы: запись архива или отдельный файл. */
sealed interface PageRef {
    val name: String

    data class InArchive(
        override val name: String,
        val archiveUri: String,
        val entry: String,
    ) : PageRef

    data class File(
        override val name: String,
        val uri: String,
    ) : PageRef
}

/** Обложка: либо файл обложки манги, либо первая страница главы. */
sealed interface Cover {
    data class FromFile(val uri: String) : Cover
    data class FromPage(val page: PageRef) : Cover
}

/**
 * Локальная библиотека поверх источника документов.
 *
 * Ни Android, ни SAF: всё через [DocumentSource]. Поэтому правила проверяются
 * тестами на настоящих папках и zip-файлах, а не догадками на устройстве.
 */
class LocalLibrary(private val source: DocumentSource) {

    /** Манги в корне: папки и одиночные архивы, служебное отброшено. */
    fun manga(rootUri: String): List<Manga> = source.children(rootUri)
        .filter { LocalRules.isManga(it) }
        .map { document ->
            Manga(
                uri = document.uri,
                name = LocalRules.mangaName(document),
                isDirectory = document.isDirectory,
                // У одиночного архива «детей» нет: он и есть глава.
                children = if (document.isDirectory) source.children(document.uri) else emptyList(),
            )
        }
        .sortedWith { a, b -> naturalOrder(a.name, b.name) }

    /** Главы манги в порядке чтения: том 1, том 2, … том 10. */
    fun chapters(manga: Manga): List<Chapter> {
        if (!manga.isDirectory) {
            // Одиночный архив — манга с одной главой.
            return listOf(
                Chapter(uri = manga.uri, name = manga.name, isDirectory = false, isFolder = false),
            )
        }
        return manga.children
            .filter { LocalRules.isChapter(it, source::children) }
            .map { document ->
                Chapter(
                    uri = document.uri,
                    name = LocalRules.chapterName(document),
                    isDirectory = document.isDirectory,
                    isFolder = document.isDirectory,
                )
            }
            .sortedWith { a, b -> naturalOrder(a.name, b.name) }
    }

    /**
     * Страницы главы в естественном порядке.
     *
     * У папки — картинки из неё, у архива — записи из центрального каталога.
     * Ничего не распаковываем: читается только оглавление архива.
     */
    fun pages(chapter: Chapter): List<PageRef> = when {
        chapter.isFolder -> source.children(chapter.uri)
            .filter { LocalRules.isImage(it) }
            .sortedWith { a, b -> naturalOrder(a.name, b.name) }
            .map { PageRef.File(name = it.name, uri = it.uri) }

        LocalRules.extensionOf(chapter.name) in LocalRules.ARCHIVE_EXTENSIONS ->
            archiveEntries(chapter.uri)
                .map { entry -> PageRef.InArchive(name = entry.substringAfterLast('/'), archiveUri = chapter.uri, entry = entry) }

        else -> emptyList()
    }

    /**
     * Обложка манги: свой файл `cover.*`, иначе первая картинка самой ранней
     * главы. Обложка из поздней главы — это уже не начало тайтла, поэтому
     * берётся именно первая по порядку.
     */
    fun cover(manga: Manga): Cover? {
        LocalRules.explicitCover(manga.children)?.let { return Cover.FromFile(it.uri) }
        val firstChapter = chapters(manga).firstOrNull() ?: return null
        pages(firstChapter).firstOrNull()?.let { return Cover.FromPage(it) }
        return null
    }

    /** Байты обложки: файл обложки либо первая страница главы. */
    fun coverBytes(manga: Manga): ByteArray? = when (val cover = cover(manga)) {
        null -> null
        is Cover.FromFile -> source.readBytes(cover.uri)
        is Cover.FromPage -> pageBytes(cover.page)
    }

    /**
     * Байты страницы. Кэш держит несколько страниц вокруг текущей, иначе
     * листание назад распаковывает архив заново на каждом шаге.
     */
    fun pageBytes(page: PageRef): ByteArray? {
        val key = keyOf(page)
        pageCache[key]?.let { return it }
        val bytes = when (page) {
            is PageRef.File -> source.readBytes(page.uri)
            is PageRef.InArchive -> readEntry(page)
        } ?: return null
        pageCache[key] = bytes
        while (pageCache.size > CACHE_PAGES) {
            val oldest = pageCache.keys.firstOrNull() ?: break
            pageCache.remove(oldest)
        }
        return bytes
    }

    fun clearCache() = pageCache.clear()

    private fun readEntry(page: PageRef.InArchive): ByteArray? {
        val opened = source.openChannel(page.archiveUri) ?: return null
        return opened.use {
            val zip = openZip(it.channel, it.size)
            try {
                val entry = zip.find(page.entry) ?: return null
                zip.read(entry)
            } finally {
                zip.close()
            }
        }
    }

    private fun archiveEntries(uri: String): List<String> {
        val opened = source.openChannel(uri) ?: return emptyList()
        return opened.use {
            openZip(it.channel, it.size).use { zip: ZipReader ->
                zip.imageEntries(LocalRules.IMAGE_EXTENSIONS).map { entry -> entry.name }
            }
        }
    }

    private fun keyOf(page: PageRef): String = when (page) {
        is PageRef.File -> page.uri
        // Разделитель не встречается в URI: без него архив «том 1/» и запись
        // «том 1 стр 2» дали бы одну и ту же пару ключа.
        is PageRef.InArchive -> page.archiveUri + '�' + page.entry
    }

    private companion object {
        const val CACHE_PAGES = 6
    }
}

package app.yomikai.shell.library

import java.io.File
import java.io.RandomAccessFile
import java.nio.channels.FileChannel
import java.nio.file.Files

/**
 * Источник документов поверх обычной папки — для тестов.
 *
 * Ключевая деталь: здесь настоящие файлы и настоящие zip, а не заглушки. Ошибки
 * прошлой версии (глава-папка без картинок, обложка не из первой главы,
 * рекурсия на третьем уровне) видны только на настоящем дереве каталогов.
 */
class FileDocumentSource(private val root: File) : DocumentSource {

    override fun children(uri: String): List<Document> {
        val file = file(uri)
        if (!file.isDirectory) return emptyList()
        return file.listFiles().orEmpty().map { of(it) }
    }

    override fun readBytes(uri: String, maxBytes: Long): ByteArray? = runCatching {
        val file = file(uri)
        if (!file.isFile || file.length() > maxBytes) return null
        Files.readAllBytes(file.toPath())
    }.getOrNull()

    override fun openChannel(uri: String): Opened? = runCatching {
        val file = file(uri)
        if (!file.isFile) return null
        val raf = RandomAccessFile(file, "r")
        Opened(channel = raf.channel, size = raf.length())
    }.getOrNull()

    private fun file(uri: String): File = File(root, uri.removePrefix(ROOT))

    private fun of(file: File): Document = object : Document {
        override val uri: String = ROOT + file.relativeTo(root).invariantSeparatorsPath
        override val name: String = file.name
        override val isDirectory: Boolean = file.isDirectory
        override val size: Long = if (file.isDirectory) 0L else file.length()
    }

    companion object {
        const val ROOT = "/"

        /** Создать файл с содержимым; каталоги создаются автоматически. */
        fun write(source: FileDocumentSource, path: String, bytes: ByteArray) {
            val file = File(source.root, path.removePrefix(ROOT))
            file.parentFile?.mkdirs()
            file.writeBytes(bytes)
        }

        fun mkdir(source: FileDocumentSource, path: String) {
            File(source.root, path.removePrefix(ROOT)).mkdirs()
        }

        fun channelOf(file: File): FileChannel = RandomAccessFile(file, "r").channel
    }
}

package app.yomikai.shell.library

import org.junit.jupiter.api.AfterEach
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import java.io.File
import java.nio.file.Files
import java.util.zip.CRC32
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/**
 * Проверка правил локальной библиотеки на настоящем дереве каталогов.
 *
 * Каждый тест — ситуация, которая в первой версии работала неверно и была
 * отправлена пользователю как «готово».
 */
class LocalLibraryTest {

    private lateinit var dir: File
    private lateinit var source: FileDocumentSource
    private lateinit var library: LocalLibrary

    @BeforeEach
    fun setUp() {
        dir = Files.createTempDirectory("library-test").toFile()
        source = FileDocumentSource(dir)
        library = LocalLibrary(source)
    }

    @AfterEach
    fun tearDown() {
        dir.deleteRecursively()
    }

    // Манга

    @Test
    fun `мангой считается папка и одиночный архив`() {
        put("Манга/Глава 1.cbz", zip("001.jpg"))
        put("Одинокий.cbz", zip("001.jpg"))

        val names = library.manga(FileDocumentSource.ROOT).map { it.name }

        assertEquals(listOf("Манга", "Одинокий"), names)
    }

    @Test
    fun `служебные папки и скрытое не становятся мангами`() {
        put("Манга/Глава 1.cbz", zip("001.jpg"))
        FileDocumentSource.mkdir(source, "downloads/что-то.cbz")
        FileDocumentSource.mkdir(source, "backup")
        FileDocumentSource.mkdir(source, ".thumbnails")
        FileDocumentSource.mkdir(source, ".секрет")

        val names = library.manga(FileDocumentSource.ROOT).map { it.name }

        assertEquals(listOf("Манга"), names)
    }

    @Test
    fun `картинка рядом с папками мангой не считается`() {
        FileDocumentSource.write(source, "обложка.jpg", png())
        FileDocumentSource.mkdir(source, "Манга")

        assertTrue(library.manga(FileDocumentSource.ROOT).none { it.name == "обложка" })
    }

    // Главы

    @Test
    fun `глава это архив или папка с картинками`() {
        put("Манга/Глава 1.cbz", zip("001.jpg"))
        FileDocumentSource.mkdir(source, "Манга/Глава 2")
        FileDocumentSource.write(source, "Манга/Глава 2/001.jpg", png())

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }
        val chapters = library.chapters(manga)

        assertEquals(listOf("Глава 1", "Глава 2"), chapters.map { it.name })
        assertTrue(chapters[1].isFolder)
    }

    @Test
    fun `пустая папка и папка без картинок главой не являются`() {
        FileDocumentSource.mkdir(source, "Манга")
        FileDocumentSource.mkdir(source, "Манга/extras")
        FileDocumentSource.mkdir(source, "Манга/Глава 1")
        FileDocumentSource.write(source, "Манга/Глава 1/001.jpg", png())
        FileDocumentSource.write(source, "Манга/extras/заметка.txt", "привет".toByteArray())

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }

        assertEquals(listOf("Глава 1"), library.chapters(manga).map { it.name })
    }

    @Test
    fun `библиотека не лезет глубже второго уровня`() {
        FileDocumentSource.mkdir(source, "Манга/Глава 1")
        FileDocumentSource.write(source, "Манга/Глава 1/001.jpg", png())
        // Картинка на третьем уровне главой быть не должна: разметка двухуровневая.
        FileDocumentSource.mkdir(source, "Манга/Глава 1/вложенная")
        FileDocumentSource.write(source, "Манга/Глава 1/вложенная/002.jpg", png())

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }
        val chapter = library.chapters(manga).single()

        assertEquals(listOf("001.jpg"), library.pages(chapter).map { it.name })
    }

    @Test
    fun `главы идут в порядке чтения а не по алфавиту`() {
        for (n in listOf(1, 2, 10, 11)) {
            FileDocumentSource.mkdir(source, "Манга/Глава $n")
            FileDocumentSource.write(source, "Манга/Глава $n/001.jpg", png())
        }

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }

        assertEquals(
            listOf("Глава 1", "Глава 2", "Глава 10", "Глава 11"),
            library.chapters(manga).map { it.name },
        )
    }

    @Test
    fun `у одиночного архива одна глава`() {
        put("Одинокий.cbz", zip("001.jpg"))

        val manga = library.manga(FileDocumentSource.ROOT).single()

        assertEquals(listOf("Одинокий"), library.chapters(manga).map { it.name })
        assertEquals(1, library.pages(library.chapters(manga).single()).size)
    }

    // Страницы

    @Test
    fun `страницы архива идут в натуральном порядке`() {
        put("Манга/Глава 1.cbz", zipOf("1.jpg", "2.jpg", "10.jpg", "003.jpg"))

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }
        val pages = library.pages(library.chapters(manga).single())

        assertEquals(listOf("1.jpg", "2.jpg", "003.jpg", "10.jpg"), pages.map { it.name })
    }

    @Test
    fun `страница читается из архива целиком`() {
        val image = png()
        put("Манга/Глава 1.cbz", zipOf("001.jpg" to image, "002.jpg" to image))

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }
        val pages = library.pages(library.chapters(manga).single())

        assertTrue(library.pageBytes(pages.first())!!.contentEquals(image))
    }

    @Test
    fun `страница из папки читается файлом`() {
        val image = png()
        FileDocumentSource.mkdir(source, "Манга/Глава 1")
        FileDocumentSource.write(source, "Манга/Глава 1/001.jpg", image)

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }
        val page = library.pages(library.chapters(manga).single()).single()

        assertTrue(library.pageBytes(page)!!.contentEquals(image))
    }

    // Обложки

    @Test
    fun `свой файл cover важнее первой страницы`() {
        put("Манга/Глава 1.cbz", zip("001.jpg"))
        val own = png(0x11)
        FileDocumentSource.write(source, "Манга/cover.png", own)

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }

        assertTrue(library.coverBytes(manga)!!.contentEquals(own))
    }

    @Test
    fun `обложка без своего файла берется из самой ранней главы`() {
        val first = png(0x22)
        val second = png(0x33)
        put("Манга/Глава 1.cbz", zipOf("001.jpg" to first))
        put("Манга/Глава 2.cbz", zipOf("001.jpg" to second))

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }

        assertTrue(library.coverBytes(manga)!!.contentEquals(first))
    }

    @Test
    fun `обложка ищется и в главе-папке`() {
        val page = png(0x44)
        FileDocumentSource.mkdir(source, "Манга/Глава 1")
        FileDocumentSource.write(source, "Манга/Глава 1/001.jpg", page)

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }

        assertTrue(library.coverBytes(manga)!!.contentEquals(page))
    }

    @Test
    fun `у пустой манги обложки нет а не падает`() {
        FileDocumentSource.mkdir(source, "Манга")

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }

        assertNull(library.cover(manga))
        assertNull(library.coverBytes(manga))
    }

    @Test
    fun `битый архив не роняет ни библиотеку ни обложку`() {
        FileDocumentSource.write(source, "Манга/Глава 1.cbz", ByteArray(2048) { 7 })

        val manga = library.manga(FileDocumentSource.ROOT).single { it.name == "Манга" }
        val chapter = library.chapters(manga).single()

        assertNotNull(chapter)
        assertTrue(library.pages(chapter).isEmpty())
        assertNull(library.cover(manga))
    }

    private fun put(path: String, bytes: ByteArray) = FileDocumentSource.write(source, path, bytes)

    private companion object {
        fun png(marker: Int = 1): ByteArray = byteArrayOf(
            0x89.toByte(), 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A,
            marker.toByte(), 0x00, 0x00, 0x00, 0x0D,
        )

        /** zip-архив с одной картинкой. */
        fun zip(vararg names: String): ByteArray = zipOf(*names.map { it to png() }.toTypedArray())

        /** zip-архив с заданными картинками. */
        fun zipOf(vararg files: Pair<String, ByteArray>): ByteArray {
            val out = java.io.ByteArrayOutputStream()
            ZipOutputStream(out).use { zip ->
                files.forEach { (name, bytes) ->
                    // Метод STORED требует размера и контрольной суммы заранее:
                    // иначе ZipOutputStream такую запись просто не пишет.
                    val entry = ZipEntry(name).apply {
                        method = ZipEntry.STORED
                        size = bytes.size.toLong()
                        compressedSize = bytes.size.toLong()
                        crc = CRC32().apply { update(bytes) }.value
                    }
                    zip.putNextEntry(entry)
                    zip.write(bytes)
                    zip.closeEntry()
                }
            }
            return out.toByteArray()
        }
    }
}

