        }
        return bytes
    }

    fun clearCache() = pageCache.clear()

    private fun readEntry(page: PageRef.InArchive): ByteArray? = runCatching {
        val opened = source.openChannel(page.ref) ?: return null
        opened.use {
            val zip = openZip(it.channel, it.size)
            try {
                val entry = zip.find(page.entry) ?: return null
                zip.read(entry)
            } finally {
