     *
     * Битый архив — это пустой список, а не исключение: один негодный файл в
     * папке не должен ронять ни список глав, ни обложку, ни всю библиотеку.
     */
    private fun archiveEntries(ref: Ref): List<String> = runCatching {
        val opened = source.openChannel(ref) ?: return emptyList()
        opened.use {
            openZip(it.channel, it.size).use { zip: ZipReader ->
                zip.imageEntries(LocalRules.IMAGE_EXTENSIONS).map { entry -> entry.name }
            }
        }
    }.getOrDefault(emptyList())

