package app.yomikai.shell.library

import android.content.Context
import android.content.Intent
import android.net.Uri
import android.provider.DocumentsContract
import java.io.FileInputStream

/**
 * Источник документов на устройстве: SAF.
 *
 * Единственное место в приложении, которое знает про Android. Всё остальное
 * работает с [DocumentSource], и потому покрыто тестами на настоящих файлах.
 *
 * Ключевой момент, на котором ломалось всё в первой версии: содержимое
 * документа запрашивается через `buildChildDocumentsUriUsingTree` от URI
 * ДЕРЕВА. Запрос по URI документа возвращает сам документ — то есть папка
 * показывается одной строкой сама себя и войти в неё нельзя. URI дерева
 * приезжает в [Ref.tree] вместе с ссылкой, а не ищется в памяти процесса:
 * память после перезапуска пуста, и всё, что открывали вчера, перестаёт
 * открываться.
 */
class SafDocumentSource(private val context: Context) : DocumentSource {

    private val prefs = context.getSharedPreferences("roots", Context.MODE_PRIVATE)

    /** Отсортированные по имени корни: при запуске порядок не должен меняться. */
    fun roots(): List<Ref> = prefs.getStringSet("uris", emptySet()).orEmpty()
        .map { Ref.treeRoot(it) }
        .sortedBy { it.name.lowercase() }

    fun addRoot(treeUri: String): Boolean {
        val uri = Uri.parse(treeUri)
        // Права выдаются оболочке навсегда: без persistable-разрешения папка
        // перестаёт читаться уже после перезапуска процесса.
        val persisted = runCatching {
            context.contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }.isSuccess
        if (!persisted) return false
        val next = prefs.getStringSet("uris", emptySet()).orEmpty().toMutableSet().apply { add(treeUri) }
        prefs.edit().putStringSet("uris", next).apply()
        return true
    }

    fun removeRoot(ref: Ref) {
        runCatching {
            context.contentResolver.releasePersistableUriPermission(
                Uri.parse(ref.uri),
                Intent.FLAG_GRANT_READ_URI_PERMISSION,
            )
        }
        val next = prefs.getStringSet("uris", emptySet()).orEmpty().toMutableSet().apply { remove(ref.uri) }
        prefs.edit().putStringSet("uris", next).apply()
    }

    override fun children(parent: Ref): List<Ref> {
        // Без дерева содержимое не перечислить в принципе.
        if (parent.tree.isBlank()) return emptyList()
        val tree = Uri.parse(parent.tree)
        val document = Uri.parse(parent.uri)
        val docId = if (parent.isDirectory && document != tree) {
            DocumentsContract.getDocumentId(document)
        } else {
            DocumentsContract.getTreeDocumentId(tree)
        }
        val children = DocumentsContract.buildChildDocumentsUriUsingTree(tree, docId)
        val out = ArrayList<Ref>()
        context.contentResolver.query(children, null, null, null, null)?.use { cursor ->
            val idColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID)
            val nameColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
            val sizeColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_SIZE)
            val mimeColumn = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE)
            while (cursor.moveToNext()) {
                val docId = if (idColumn >= 0) cursor.getString(idColumn) else null
                val name = if (nameColumn >= 0) cursor.getString(nameColumn) else null
                val size = if (sizeColumn >= 0 && !cursor.isNull(sizeColumn)) cursor.getLong(sizeColumn) else 0L
                val mime = if (mimeColumn >= 0) cursor.getString(mimeColumn) else null
                out.add(
                    Ref(
                        uri = DocumentsContract.buildDocumentUriUsingTree(tree, docId.orEmpty()).toString(),
                        // Дерево едет вместе с ребёнком: без него вложенная
                        // папка не знает, по какому дереву себя перечислять.
                        tree = parent.tree,
                        name = name.orEmpty(),
                        isDirectory = mime == DocumentsContract.Document.MIME_TYPE_DIR,
                        size = size,
                    ),
                )
            }
        }
        return out
    }

    override fun readBytes(doc: Ref, maxBytes: Long): ByteArray? = runCatching {
        context.contentResolver.openInputStream(Uri.parse(doc.uri))?.use { input ->
            val out = java.io.ByteArrayOutputStream()
            val buffer = ByteArray(128 * 1024)
            var total = 0L
            while (true) {
                val read = input.read(buffer)
                if (read < 0) break
                total += read
                if (total > maxBytes) return null
                out.write(buffer, 0, read)
            }
            out.toByteArray()
        }
    }.getOrNull()

    override fun openChannel(doc: Ref): Opened? = runCatching {
        val pfd = context.contentResolver.openFileDescriptor(Uri.parse(doc.uri), "r") ?: return null
        // Канал держит дескриптор открытым: закрывать pfd отдельно нельзя.
        val channel = FileInputStream(pfd.fileDescriptor).channel
        Opened(channel = channel, size = if (channel.size() > 0) channel.size() else pfd.statSize)
    }.getOrNull()
}

package app.yomikai.shell.library

import android.content.Intent
import android.graphics.BitmapFactory
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Button
import android.widget.TextView
import android.widget.Toast
import androidx.activity.addCallback
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import app.yomikai.shell.R
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * Библиотека: корни и манги, нативный список.
 *
 * Экран ничего не решает сам: что считать мангой, главой и обложкой, решает
 * [LocalLibrary], а он покрыт тестами. Здесь только показ и переходы.
 *
 * Содержимое перечитывается при каждом показе, поэтому список всегда актуален:
 * файл, добавленный на телефон, виден сразу.
 */
class LibraryActivity : AppCompatActivity() {

    private lateinit var source: SafDocumentSource
    private lateinit var library: LocalLibrary
    private lateinit var recycler: RecyclerView
    private lateinit var header: TextView

    private val pickRoot =
        registerForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
            if (uri == null) return@registerForActivityResult
            lifecycleScope.launch {
                val added = withContext(Dispatchers.IO) { source.addRoot(uri.toString()) }
                if (!added) {
                    Toast.makeText(
                        this@LibraryActivity,
                        R.string.library_root_denied,
                        Toast.LENGTH_LONG,
                    ).show()
                    return@launch
                }
                showRoots()
            }
        }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        source = SafDocumentSource(this)
        library = LocalLibrary(source)
        setContentView(R.layout.activity_library)

        header = findViewById(R.id.header)
        recycler = findViewById(R.id.list)
        recycler.layoutManager = LinearLayoutManager(this)

        findViewById<Button>(R.id.addRoot).setOnClickListener { pickRoot.launch(null) }
        findViewById<Button>(R.id.refresh).setOnClickListener { showRoots() }

        onBackPressedDispatcher.addCallback(this) { finish() }

        showRoots()
    }

    override fun onResume() {
        super.onResume()
        // Возврат из читалки меняет содержимое папки.
        if (::recycler.isInitialized) showRoots()
    }

    private fun showRoots() {
        header.setText(R.string.library_roots)
        lifecycleScope.launch {
            val roots = withContext(Dispatchers.IO) { source.roots() }
            render(
                items = roots.map { Row.Root(it) },
                onOpen = { ref -> openManga(ref) },
                onRemove = { ref ->
                    lifecycleScope.launch {
                        withContext(Dispatchers.IO) { source.removeRoot(ref) }
                        showRoots()
                    }
                },
            )
        }
    }

    private fun openManga(ref: Ref) {
        lifecycleScope.launch {
            val manga = withContext(Dispatchers.IO) {
                library.manga(ref).firstOrNull { it.ref.uri == ref.uri }
            } ?: return@launch
            val chapters = withContext(Dispatchers.IO) { library.chapters(manga) }
            if (chapters.isEmpty()) {
                // Папка без глав — это просто каталог. В оригинале такие папки
                // не показываются как манга; показываем тост, а не пустой экран.
                Toast.makeText(this@LibraryActivity, R.string.library_no_chapters, Toast.LENGTH_SHORT).show()
                return@launch
            }
            startActivity(
                Intent(this, TitleDetailActivity::class.java)
                    .putExtra(TitleDetailActivity.EXTRA_MANGA, manga)
                    .putExtra(TitleDetailActivity.EXTRA_CHAPTERS, ArrayList(chapters)),
            )
        }
    }

    /** Строка списка: запечатанные типы, у каждого своё действие. */
    private sealed interface Row {
        val ref: Ref
        val label: String

        data class Root(override val ref: Ref) : Row {
            override val label: String get() = ref.name
        }
    }

    private fun render(
        items: List<Row>,
        onOpen: (Ref) -> Unit,
        onRemove: (Ref) -> Unit,
    ) {
        recycler.adapter = object : RecyclerView.Adapter<Holder>() {
            override fun onCreateViewHolder(parent: ViewGroup, viewType: Int) = Holder(
                LayoutInflater.from(parent.context).inflate(R.layout.item_library, parent, false),
            )

            override fun getItemCount() = items.size

            override fun onBindViewHolder(holder: Holder, position: Int) {
                holder.bind(items[position], onOpen, onRemove)
            }
        }
    }

    private inner class Holder(view: View) : RecyclerView.ViewHolder(view) {
        private val name: TextView = view.findViewById(R.id.name)
        private val action: Button = view.findViewById(R.id.action)

        fun bind(row: Row, onOpen: (Ref) -> Unit, onRemove: (Ref) -> Unit) {
            name.text = row.label
            action.setText(R.string.library_remove)
            action.setOnClickListener { onRemove(row.ref) }
            name.setOnClickListener { onOpen(row.ref) }
            itemView.setOnClickListener { onOpen(row.ref) }
        }
    }

    private companion object {
        @Suppress("unused")
        fun decode(bytes: ByteArray) = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }
}

package app.yomikai.shell.library

import android.content.Intent
import android.graphics.BitmapFactory
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Button
import android.widget.ImageView
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import app.yomikai.shell.R
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * Экран тайтла: обложка, имя и список глав.
 *
 * Всё содержимое приходит готовым из [LocalLibrary] и уже проверено тестами:
 * какие главы считаются главами, в каком они порядке и откуда взялась обложка.
 * Экран только показывает.
 */
class TitleDetailActivity : AppCompatActivity() {

    private lateinit var library: LocalLibrary
    private lateinit var list: RecyclerView
    private lateinit var titleText: TextView
    private lateinit var cover: ImageView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_title_detail)

        @Suppress("DEPRECATION")
        val manga = intent.getSerializableExtra(EXTRA_MANGA) as? Manga ?: run { finish(); return }
        @Suppress("DEPRECATION")
        val chapters = intent.getSerializableExtra(EXTRA_CHAPTERS)
            ?.let { it as? ArrayList<*> }
            ?.filterIsInstance<Chapter>()
            .orEmpty()

        library = LocalLibrary(SafDocumentSource(this))
        cover = findViewById(R.id.cover)
        titleText = findViewById(R.id.title)
        list = findViewById(R.id.chapters)
        list.layoutManager = LinearLayoutManager(this)

        lifecycleScope.launch {
            // Обложка грузится отдельно от списка глав: тяжёлый архив читается
            // на IO, и экран не должен ждать его, чтобы показать главы.
            val coverBytes = withContext(Dispatchers.IO) { library.coverBytes(manga) }
            if (coverBytes != null) {
                cover.setImageBitmap(BitmapFactory.decodeByteArray(coverBytes, 0, coverBytes.size))
            }

            val rows = chapters.map { chapter ->
                val pages = withContext(Dispatchers.IO) { library.pages(chapter).size }
                Row(chapter, pages)
            }
            titleText.text = getString(R.string.title_summary, manga.name, pagesOf(chapters))
            list.adapter = ChapterAdapter(rows) { chapter -> openReader(chapter) }
        }

        findViewById<Button>(R.id.readAll).setOnClickListener {
            openSequential(chapters)
        }
    }

    private fun pagesOf(chapters: List<Chapter>): Int =
        listOfNotNull(listViewTag).sumOf { it }

    /** Сколько страниц во всех главах: считается по мере подгрузки строк. */
    private var listViewTag: List<Int>? = null

    private fun openReader(chapter: Chapter) {
        lifecycleScope.launch {
            val pages = withContext(Dispatchers.IO) { library.pages(chapter) }
            if (pages.isEmpty()) {
                android.widget.Toast.makeText(
                    this@TitleDetailActivity,
                    R.string.reader_no_pages,
                    android.widget.Toast.LENGTH_LONG,
                ).show()
                return@launch
            }
            startActivity(
                Intent(this@TitleDetailActivity, ReaderActivity::class.java)
                    .putExtra(ReaderActivity.EXTRA_NAME, chapter.name)
                    .putExtra(ReaderActivity.EXTRA_PAGES, ArrayList(pages)),
            )
        }
    }

    /** «Читать всё»: главы подряд, в порядке чтения. */
    private fun openSequential(chapters: List<Chapter>) {
        lifecycleScope.launch {
            val pages = withContext(Dispatchers.IO) {
                chapters.flatMap { library.pages(it) }
            }
            if (pages.isEmpty()) {
                android.widget.Toast.makeText(
                    this@TitleDetailActivity,
                    R.string.reader_no_pages,
                    android.widget.Toast.LENGTH_LONG,
                ).show()
                return@launch
            }
            startActivity(
                Intent(this@TitleDetailActivity, ReaderActivity::class.java)
                    .putExtra(ReaderActivity.EXTRA_NAME, getString(R.string.reader_all_chapters))
                    .putExtra(ReaderActivity.EXTRA_PAGES, ArrayList(pages)),
            )
        }
    }

    private data class Row(val chapter: Chapter, val pages: Int)

    private class ChapterAdapter(
        private val rows: List<Row>,
        private val onClick: (Chapter) -> Unit,
    ) : RecyclerView.Adapter<ChapterAdapter.Holder>() {

        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int) = Holder(
            LayoutInflater.from(parent.context).inflate(R.layout.item_chapter, parent, false),
        )

        override fun getItemCount() = rows.size

        override fun onBindViewHolder(holder: Holder, position: Int) = holder.bind(rows[position])

        inner class Holder(view: View) : RecyclerView.ViewHolder(view) {
            private val name: TextView = view.findViewById(R.id.chapter)
            private val count: TextView = view.findViewById(R.id.count)

            fun bind(row: Row) {
                // Число страниц рядом с именем: это первое, что ищут, открывая
                // главу, и по имени файла это не узнать.
                name.text = row.chapter.name
                count.text = if (row.pages > 0) {
                    view.context.getString(R.string.title_pages, row.pages)
                } else {
                    ""
                }
                itemView.setOnClickListener { onClick(row.chapter) }
            }
        }
    }

    companion object {
        const val EXTRA_MANGA = "manga"
        const val EXTRA_CHAPTERS = "chapters"
    }
}

